        ('Yabuta Outlaws', 'Wants to avoid the kind of debt, punishment, or humiliation that can follow one bad day around Yabuta Outlaws. Would like to be trusted with slightly better work than the scraps nobody else wants. Also hopes to keep one reliable ally nearby, even if that only means someone who will not sell them out cheaply.', '')
), normalized AS (
    SELECT DISTINCT TRIM(faction) AS faction, TRIM(description) AS description, LOWER(TRIM(gender)) AS gender
    FROM source_rows
    WHERE TRIM(faction) <> '' AND TRIM(description) <> ''
)
INSERT INTO bio_random (type, description, name, race, gender, faction)
SELECT 'goals', n.description, '', '', n.gender, n.faction
FROM normalized n
ON CONFLICT (type, description, name) DO NOTHING;
COMMIT;
